# Break My Fix finding 1, generated by Tracefix: AbstractPackageReference.normalize_packages returns a wrong value.
# Property (signature): normalize_packages returns a set of package name strings
# Quote: def normalize_packages(packages: set[str]) -> set[str]:
# Run it with pytest: it fails for as long as the code breaks this property.

from twyn.trusted_packages.references.base import AbstractPackageReference


def test_break_my_fix_1() -> None:
    packages = {''}
    result = AbstractPackageReference.normalize_packages(packages={''})
    assert (isinstance(result, set) and all(isinstance(p, str) for p in result))
